import numpy as np


def _weighted_median(data, weights):
    data = np.asarray(data)
    if weights is not None:
        weights = np.asarray(weights)

    mask = ~np.isnan(data)
    data = data[mask]
    if weights is not None:
        weights = weights[mask]

    if len(data) == 0:
        return np.nan

    if weights is None:
        weights = np.ones_like(data)

    if weights.sum() == 0:
        return np.nan

    idx = np.argsort(data)
    sorted_data = data[idx]
    sorted_weights = weights[idx]

    cum_weights = np.cumsum(sorted_weights)
    total_weight = cum_weights[-1]

    median_idx = np.searchsorted(cum_weights, 0.5 * total_weight)

    if median_idx >= len(sorted_data):
        return sorted_data[-1]

    return sorted_data[median_idx]


def weekly_kpi(actual, forecast, demand_weight):
    \"\"\"Demand-weighted median absolute forecast error for one week (lower is better).\"\"\"
    errors = np.abs(np.asarray(actual) - np.asarray(forecast))
    return float(_weighted_median(errors, demand_weight))

